@font-face{font-family:Plex;src:url("data:font/ttf;base64,")}@font-face{font-family:Lora;src:url("data:font/ttf;base64,")}@font-face{font-family:Cormorant;src:url("data:font/ttf;base64,");font-style:italic}
*{box-sizing:border-box}body{margin:0;background:#eae6dd;color:#293e42;font-family:Plex,sans-serif}header,main{max-width:1280px;margin:auto;padding:0 32px}header{display:flex;justify-content:space-between;align-items:center;padding-top:32px}.brand{font-family:Lora;font-size:28px;text-decoration:none;color:inherit}header>span,.eyebrow{font-size:10px;letter-spacing:1.8px}.intro{display:flex;justify-content:space-between;align-items:end;margin:48px 0 40px;gap:32px}h1,h2,h3{font-family:Lora;font-weight:400}h1{font-size:46px;letter-spacing:-1.5px;margin:12px 0 16px}.intro p:not(.eyebrow){font-size:15px;line-height:1.7;color:#65716b}.intro aside{font-size:12px;line-height:1.8;border-left:1px solid #b7bdb1;padding:8px 0 8px 24px}.intro aside b{font-weight:400}.intro aside small{display:block;color:#65716b}.directions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.direction-label{display:flex;justify-content:space-between;gap:8px;font-size:12px;padding:0 8px;margin-bottom:16px}.direction-label b{font-weight:400}.direction-label>span{font-size:8px;color:#975039;letter-spacing:1px}.phone{height:840px;display:flex;flex-direction:column;border:1px solid #c3c5b8;border-radius:36px;overflow:hidden;background:#fcf6ec;box-shadow:0 24px 32px -24px #694a3a66}.status{height:40px;background:#f1dfd0;padding:12px 24px 0;display:flex;justify-content:space-between;font-size:11px;position:relative}.camera{position:absolute;top:8px;left:50%;transform:translateX(-50%);width:72px;height:20px;background:#44342d;border-radius:30px}.toolbar{height:52px;display:flex;align-items:center;padding:0 20px;gap:20px;background:#f1dfd0;border-bottom:1px solid #dfcbbb;font-size:12px}.toolbar span:first-child{flex:1;display:flex;align-items:center;gap:8px}.toolbar img{width:20px;height:20px;filter:brightness(.35)}.viewport{flex:1;overflow:auto;scrollbar-width:none}.cover{padding:32px 20px 0;text-align:center}.cover .eyebrow{font-size:8px;color:#806b5b;letter-spacing:1.7px}.cover h2{font-family:Cormorant;font-style:italic;font-size:64px;line-height:1.1;letter-spacing:-1px;margin:8px 0}.subtitle{font-size:12px;color:#806b5b;margin:0 0 24px}.art{width:100%;display:block;aspect-ratio:600/640;object-fit:contain;border-radius:3px}.art-caption{font-size:8px;letter-spacing:1.6px;color:#806b5b;margin:16px 0 28px}.henry{border-top:1px solid #dfd0bf;padding:24px}.byline{font-size:9px;display:flex;justify-content:space-between;color:#806b5b}.byline span:first-child{font-size:8px;letter-spacing:1.4px}.henry h3{font-size:25px;line-height:1.3;margin:16px 0}.henry>p{font-family:Lora;font-size:15px;line-height:1.85;color:#5f5549}.read-intro,.start{display:flex;width:100%;justify-content:space-between;align-items:center;font:inherit;font-size:12px;min-height:44px;padding:12px 16px;border:0;border-radius:12px;background:#e9ddcb;color:#44342d;text-decoration:none;margin-top:16px;cursor:pointer}.start{background:#9d4634;color:#fff9ee}.read-intro:focus-visible,a:focus-visible,button:focus-visible{outline:3px solid #b36e39;outline-offset:3px}nav{height:64px;flex-shrink:0;background:#fffdfa;border-top:1px solid #dfd0bf;display:flex;align-items:center;justify-content:space-around}nav div{display:grid;justify-items:center;gap:4px;color:#806b5b}nav img{width:21px;height:21px;filter:brightness(.45)}nav small{font-size:9px}nav .active{color:#9d4634}nav .active img{filter:brightness(.3)}.home{height:12px;background:#fffdfa;position:relative}.home:after{content:'';position:absolute;top:0;left:calc(50% - 50px);width:100px;height:4px;background:#806b5b;border-radius:10px}.caption{padding:20px 8px 0}.caption h3{font-size:17px;margin:0 0 8px}.caption p{font-size:12px;line-height:1.75;color:#65716b;margin:0 0 12px}.caption a,.gallery a{font-size:11px;color:#975039;text-underline-offset:4px}.collection{margin-top:72px;border-top:1px solid #bfc3b7;padding-top:40px}.series-head{display:flex;justify-content:space-between;gap:32px;align-items:end;margin-bottom:32px}.series-head h2,.principles h2{font-size:32px;letter-spacing:-1px;margin:12px 0 0}.series-head>p{font-size:13px;line-height:1.8;color:#65716b;max-width:380px;margin:0}.gallery{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px}.gallery img{width:100%;display:block}.gallery h3{font-family:Cormorant;font-style:italic;font-size:38px;margin:8px 0}.gallery .eyebrow{font-size:8px;letter-spacing:.8px;margin-top:20px}.gallery p:not(.eyebrow){font-size:13px;color:#65716b;margin:0 0 16px}.principles{border-top:1px solid #bfc3b7;margin-top:64px;padding:40px 0;display:grid;grid-template-columns:1fr 1fr;gap:64px}.principles ol{margin:0;padding-left:20px;display:grid;gap:16px;font-size:13px;line-height:1.75;color:#65716b}.principles b{font-weight:400;color:#293e42}footer{border-top:1px solid #bfc3b7;padding:24px 0 32px;font-size:11px;line-height:1.8;color:#65716b}dialog{max-width:620px;width:calc(100% - 32px);max-height:85vh;overflow:auto;padding:40px;border:1px solid #dfd0bf;border-radius:24px;background:#fcf6ec;color:#44342d}dialog::backdrop{background:#253d4377;backdrop-filter:blur(5px)}dialog h2{font-family:Cormorant;font-style:italic;font-size:52px;margin:20px 0}dialog #full{font-family:Lora;font-size:17px;line-height:1.9}dialog small{font-size:11px;line-height:1.7;color:#806b5b}.close{float:right;width:44px;height:44px;border:0;border-radius:50%;font-size:26px;background:#e9ddcb;color:#44342d;cursor:pointer}@media(max-width:900px){.directions{grid-template-columns:repeat(3,340px);overflow:auto;scroll-snap-type:x proximity;margin:0 -24px;padding:0 24px 32px}.directions article{scroll-snap-align:center}header,main{padding-left:24px;padding-right:24px}.intro{align-items:start;flex-direction:column}.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.series-head{flex-direction:column;align-items:start}.principles{grid-template-columns:1fr;gap:24px}h1{font-size:36px}}@media(max-width:420px){.directions{grid-template-columns:repeat(3,calc(100vw - 48px))}.phone{height:800px}.cover h2{font-size:56px}header>span{font-size:8px}.gallery{gap:16px}.gallery .eyebrow{line-height:1.7}.gallery h3{font-size:32px}}
